css:
.bz-section[data-bz-node="so"]{padding-block:clamp(56px,6vw,96px)}
[data-bz-node="so"] .bz-block{padding-block:0}
[data-bz-node="so-intro"] p{font-size:.9375rem;line-height:1.75;max-width:40rem;margin:0}
[data-bz-node="so-intro"] p:empty{display:none}
[data-bz-node="so-grid"]{margin-top:var(--space-6);border-top:1px solid var(--line);border-left:1px solid var(--line)}
[data-bz-node="so-grid"]>.bz-col{border-right:1px solid var(--line);border-bottom:1px solid var(--line);padding:clamp(22px,2.4vw,32px);display:flex;flex-direction:column;gap:var(--space-3);transition:background-color .18s ease}
[data-bz-node="so-grid"]>.bz-col:hover{background:var(--paper)}
[data-bz-node^="so-eyebrow"] p{font:700 .625rem/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:var(--muted);margin:0}
[data-bz-node^="so-eyebrow"] p:empty{display:none}
[data-bz-node^="so-title"] h3{font:700 .9375rem/1.3 var(--font-heading);text-transform:uppercase;margin:0}
[data-bz-node^="so-body"] p{font-size:.8125rem;line-height:1.75;color:#4a4945;margin:0}
[data-bz-node^="so-link"]{margin-top:auto}
[data-bz-node^="so-link"] p{margin:0}
[data-bz-node^="so-link"] a{font:700 .6875rem/1 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:var(--ink);text-decoration:none}
[data-bz-node^="so-link"] a::after{content:" \2192"}
[data-bz-node^="so-link"] a:hover{text-decoration:underline}
[data-bz-node^="so-link"] a[href=""],[data-bz-node^="so-link"] a:empty{display:none}
@media (max-width:1100px){[data-bz-node="so-grid"]>.bz-col{grid-column:span 6}}
@media (max-width:640px){[data-bz-node="so-grid"]>.bz-col{grid-column:1/-1}}
